import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import { Button, Menu, Dropdown, Icon, Row, Col, Input, Card, Tag, Spin, Tooltip, Table } from 'antd'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import UmbrellaReportStyleWrapper from './gocar.style'
import gocarAction from '../../../redux/gocar/actions'
import XLSX from 'xlsx'
import downloader from '../../../../helpers/downloader'
import moment from 'moment'

const SEARCH_STORAGE_KEY = 'gocar_upload_detail_search'

const { getDetailUploadList, downloadRows } = gocarAction

class AgentTable extends PureComponent {
  constructor (props) {
    super(props)
    const savedSearch = localStorage.getItem(SEARCH_STORAGE_KEY) || ''
    this.state = {
      dataSource: [],
      filteredData: [],
      searchInput: savedSearch,
      columns: [],
      loader: false
    }
  }

  applySearch = (data, searchValue) => {
    if (!searchValue) return data
    const searchLower = searchValue.toLowerCase()
    return data.filter(record =>
      Object.values(record).some(val =>
        val && val.toString().toLowerCase().includes(searchLower)
      )
    )
  }

  componentWillReceiveProps (nextProps) {
    const { fileDetail } = nextProps
    const { data } = nextProps.gocarData
    if (Object.keys(fileDetail).length > 0 && fileDetail.headers) {
      const columns = fileDetail.headers.map((val, index) => {
        const [headerName, field] = val
        const columnDef = {
          title: headerName,
          dataIndex: field || '',
          key: `col_${index}`,
          sorter: (a, b) => {
            const aVal = a[field] || ''
            const bVal = b[field] || ''
            return aVal.toString().localeCompare(bVal.toString())
          }
        }

        // Add extra width for Error column
        if (headerName === 'Error') {
          columnDef.width = 400
        }

        // Handle Error column rendering
        if (headerName === 'Error') {
          columnDef.render = (text) => text === '[]' ? '' : text
        }

        return columnDef
      })

      const rows = (fileDetail.rows && fileDetail.rows.length > 0) ? data.rows : []
      this.setState({
        columns,
        dataSource: rows,
        filteredData: this.applySearch(rows, this.state.searchInput),
        loader: false
      })
    }
  }

  componentDidMount () {
    this.setState({ loader: true })
    if (this.props.location.state !== undefined) {
      const { data } = this.props.location.state.params
      this.props.getDetailUploadList(data.id)
    } else {
      const { location } = this.props
      const id = location.pathname.substring(location.pathname.lastIndexOf('/') + 1)
      if (typeof id === 'string') {
        this.props.getDetailUploadList(id)
      }
    }
  }

  dateGenerator = () => {
    let today = new Date()
    let dd = today.getDate()
    let mm = today.getMonth() + 1 // January is 0!
    let yyyy = today.getFullYear()
    if (dd < 10) dd = '0' + dd
    if (mm < 10) mm = '0' + mm
    let assignment = today = mm + '-' + dd + '-' + yyyy
    return assignment
  }

  exportToExcel () {
    const { filteredData } = this.state
    const worksheet = XLSX.utils.json_to_sheet(filteredData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Upload Details')
    const xlsxContent = XLSX.write(workbook, { bookType: 'xlsx', type: 'base64' })
    const params = {
      fileName: 'upload_list_data_' + this.dateGenerator()
    }
    downloader(params, xlsxContent)
  }

  onClearFilter = () => {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.setState({
      searchInput: '',
      filteredData: this.state.dataSource
    })
  }

  onFilterChange = (val) => {
    const searchValue = val.target.value
    localStorage.setItem(SEARCH_STORAGE_KEY, searchValue)
    this.setState({
      searchInput: searchValue,
      filteredData: this.applySearch(this.state.dataSource, searchValue)
    })
  }

  downloadUploadedDoc (filename, uri) {
    let link = document.createElement('a')
    link.download = filename
    link.href = uri
    link.click()
  }

  handleDownload = (type) => {
    this.props.downloadRows({ body: { type }, params: { templateId: this.props.location.state.params.data.id } })
  }

  onBackUploadList = () => {
    const { history } = this.props
    history.push('/gocar/upload-list')
  }

  render () {
    const { fileDetail = {} } = this.props
    const { filteredData, searchInput, columns, loader } = this.state
    const menu = (
      <Menu onClick={this.exportToExcel.bind(this)}>
        <Menu.Item key='1'><Icon type='right-circle-o' /> Excel</Menu.Item>
      </Menu>
    )

    return (
      <UmbrellaReportStyleWrapper>
        <LayoutContentWrapper className='referral-table'>
          <Row style={{ width: '100%', marginBottom: '30px' }}>
            <Spin tip='Loading ...' spinning={loader}>
              <Col span={24}>
                <Card bordered={false}>
                  <Row type='flex' align='middle'>
                    <Button
                      type='primary'
                      onClick={this.onBackUploadList}
                      style={{ marginRight: '20px' }}
                    >
                      <Icon type='left' />Back
                    </Button>
                    <h3>File Detail</h3>
                  </Row>
                  <Row type='flex' justify='space-between'>
                    <h4>Filename : &nbsp; {fileDetail.filename}</h4>
                    <Tooltip placement='topLeft' title='Download uploaded file'>
                      <Button type='primary' onClick={() => this.downloadUploadedDoc(fileDetail.filename, fileDetail.file_url)}><Icon type='cloud' /> Download file</Button>
                    </Tooltip>
                  </Row>
                  <Row>
                    <h4>Status : &nbsp; {fileDetail.status &&
                      <Tag color='cyan'>{fileDetail.status}</Tag>}</h4>
                  </Row>
                  <Row>
                    <h4>Notes : &nbsp; {fileDetail.errors && (fileDetail.errors !== '[]' && <Tag color='red'>{fileDetail.errors}</Tag>)}</h4>
                  </Row>
                  <Row>
                    <h4>Uploaded At : &nbsp; {fileDetail.uploadedAt !== '' ? moment(fileDetail.uploadedAt).format('DD MMMM YYYY HH:mm:ss') : '-'}</h4>
                  </Row>
                  <Row>
                    <h4>Request Payload: &nbsp; {fileDetail.request_payload}</h4>
                  </Row>
                </Card>
              </Col>
            </Spin>
          </Row>
          <LayoutContent style={{ padding: '4vh', height: '100vh' }}>
            <Row type='flex' justify='space-between' align='middle'>
              <h3>File Rows Detail</h3>
              <Row type='flex'>
                <Button style={{ marginRight: '10px' }} onClick={this.onClearFilter}><Icon type='filter' /> Clear filters</Button>
                <Input value={searchInput} type='text' id='filter-text-box' placeholder='Search...' onInput={val => this.onFilterChange(val)} style={{ width: '200px', borderRadius: '0px', marginRight: '10px' }} />
                <Dropdown overlay={menu}>
                  <Button style={{ marginRight: '10px' }}>Export to <Icon type='down' /></Button>
                </Dropdown>
                <Button type='primary' style={{ marginRight: '10px' }} onClick={() => this.handleDownload('SUCCESS')}>
                  Download Success ({fileDetail.row_status && (fileDetail.row_status.SUCCESS || 0)})
                </Button>
                <Button type='danger' style={{ marginRight: '10px' }} onClick={() => this.handleDownload('FAILED')}>
                  Download Failed ({fileDetail.row_status && (fileDetail.row_status.FAILED || 0)})
                </Button>
                {
                  fileDetail.template === 'UPDATE_GOCAR_COMPLETE_PAYMENT_DETAILS' &&
                  <Button type='danger' style={{ marginRight: '10px' }} onClick={() => this.handleDownload('DATA_MISMATCH')}>
                    Download Mismatched Data ({fileDetail.row_status && (fileDetail.row_status.DATA_MISMATCH || 0)})
                  </Button>
                }
              </Row>
            </Row>
            <Table
              columns={columns}
              dataSource={filteredData}
              rowKey={(record, index) => index}
              pagination={{
                pageSize: 10,
                showSizeChanger: true,
                showTotal: (total, range) => `[${range[0]}-${range[1]}] of ${total} items`
              }}
              locale={{
                emptyText: 'Data is empty :('
              }}
              style={{ marginTop: '16px' }}
              scroll={{ x: 'max-content' }}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      </UmbrellaReportStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    gocarData: state.Gocar,
    fileDetail: state.Gocar.fileDetail
  }),
  {
    getDetailUploadList,
    downloadRows
  }
)(AgentTable)
